/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 /Library/Developer/CommandLineTools/usr/bin/python3 -c 'import lib; samples=(1,2,10**100); assert all(lib.validate_positive_integer(x) is x for x in samples); bad_type=(True,False,1.0,\"1\",None,object(),[1],(1,),{1}, {\"x\":1}, 1+0j, b\"1\"); bad_value=(0,-1,-10**100); [(lambda v: (_ for _ in ()).throw(AssertionError(v)) if False else None)(v) for v in ()]; print(\"identity\", len(samples));
for v in bad_type:
 try: lib.validate_positive_integer(v)
 except TypeError: pass
 else: raise AssertionError((\"expected TypeError\",repr(v)))
for v in bad_value:
 try: lib.validate_positive_integer(v)
 except ValueError: pass
 else: raise AssertionError((\"expected ValueError\",repr(v)))
print(\"error cases\", len(bad_type)+len(bad_value))'"

